from typing import List, Tuple
import math

def is_odd_prime(n: int) -> bool:
    if n < 3 or n % 2 == 0:
        return False
    for d in range(3, int(math.isqrt(n)) + 1, 2):
        if n % d == 0:
            return False
    return True

def eisenstein_floor_sum(q: int, p: int) -> int:
    return sum((x * q) // p for x in range(1, (p - 1) // 2 + 1))

def verify_all(limit: int) -> int:
    primes: List[int] = [n for n in range(3, limit) if is_odd_prime(n)]
    failures: int = 0
    for p in primes:
        for q in primes:
            if p == q:
                continue
            s_qp, s_pq = eisenstein_floor_sum(q, p), eisenstein_floor_sum(p, q)
            lhs = (-1 if s_qp % 2 else 1) * (-1 if s_pq % 2 else 1)
            rhs = -1 if ((p // 2) * (q // 2)) % 2 else 1
            rect = ((p - 1) // 2) * ((q - 1) // 2)
            if lhs != rhs or s_qp + s_pq != rect:
                failures += 1
    return failures

if __name__ == '__main__':
    print('failures below 50:', verify_all(50))

import cmath
from typing import List, Tuple

def legendre_symbol(a: int, p: int) -> int:
    a_mod = a % p
    if a_mod == 0:
        return 0
    r = pow(a_mod, (p - 1) // 2, p)
    return -1 if r == p - 1 else r

def gauss_sum_square_check(p: int) -> Tuple[complex, complex]:
    g = sum(legendre_symbol(x, p) * cmath.exp(2j * cmath.pi * x / p)
            for x in range(p))
    sign = -1 if ((p - 1) // 2) % 2 else 1
    return g * g, complex(sign * p, 0.0)

if __name__ == '__main__':
    for p in [3, 5, 7, 11, 13, 17, 19, 23]:
        g2, pred = gauss_sum_square_check(p)
        print(p, round(g2.real, 4), round(g2.imag, 4), '==', pred.real,
              abs(g2 - pred) < 1e-6)

