    S_qp <- 0
    for x in 1 .. (p-1)//2:
        S_qp <- S_qp + floor(x*q / p)
    S_pq <- 0
    for y in 1 .. (q-1)//2:
        S_pq <- S_pq + floor(y*p / q)
    assert S_qp + S_pq == ((p-1)//2) * ((q-1)//2)   # rectangle identity
    legendre_qp <- (-1)^(S_qp mod 2)
    legendre_pq <- (-1)^(S_pq mod 2)
    return legendre_qp * legendre_pq                 # = (-1)^(floor(p/2)*floor(q/2))

